/**
 * @description
 */

let KnifeType = {
    Coin: 1,
    ExtraPick: 2,
    MultAndExtraPick: 3,
    GodAthena: 4,
}

cc.Class({
    extends: cc.Component,
    properties: {
        remainTimes: cc.Node,


        _winCoin: 0,

        _canSelect: true,

        _betCoin: 0,
        _successCallback: null,
        _curRateItemIndex: 0,
        _restCnt: 0,

        _haveOpenReward: [],
    },

    enterGame(data, success) {
        cc.vv.AudioManager.playBgm("games/GodAthena/", "jp_celebration", true);
        this.node.active = true;
        this._haveOpenReward = [];
        this._restCnt = data.restCnt;
        this._successCallback = success;

        this.regiserClickEvent();

        this.reset();

        for (let i = 0; i < data.choiceIdxs.length; i++) {
            let idx = data.choiceIdxs[i];
            let knife = cc.find("knife_" + idx, this.node);
            if (knife) {
                this._showRewardByType(knife, data.choiceItems[i]);
            }
        }

        this._updateRemainTimes();
    },

    exitGame() {
        this.node.active = false;
    },

    _updateRemainTimes() {
        this.remainTimes.getComponent(cc.Label).string = this._restCnt;
    },

    async onChooseKnife(data) {
        let curChoice = data.choiceId;
        this._haveOpenReward.push(curChoice);

        // 更新次数
        this._restCnt = data.knifeGame.restCnt;

        let knife = this.node.getChildByName("knife_" + curChoice);
        // 循环动画结束
        knife.getChildByName("bishouxunhuan").active = false;
        // 点击动画播放，播放完之后设置奖励
        let bishoudianji = knife.getChildByName("bishoudianji");
        let spine_bishoudianji = bishoudianji.getComponent(sp.Skeleton);
        bishoudianji.active = true;
        spine_bishoudianji.clearTracks();
        spine_bishoudianji.setToSetupPose();
        spine_bishoudianji.setAnimation(0, "animation", false);
        spine_bishoudianji.setCompleteListener(()=>{
            bishoudianji.active = false;
        });

        switch (data.item.type) {
            case KnifeType.Coin: {
                let pick1_fazhen = knife.getChildByName("pick1_fazhen");
                let pick1_fazhen_spine = pick1_fazhen.getComponent(sp.Skeleton);
                pick1_fazhen.active = true;
                pick1_fazhen_spine.clearTracks();
                pick1_fazhen_spine.setToSetupPose();
                pick1_fazhen_spine.setAnimation(0, "animation", true);

                this._showRewardByType(knife, data.item);

                await this.awaitTime(1);
                // 如果有倍数，先翻倍
                if (this._curRateItemIndex !== 0) {
                    let rateKnife = cc.find("knife_" + this._curRateItemIndex, this.node);
                    let startPos = rateKnife.convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                    let endPos = knife.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                    this._generateParticle(startPos, endPos);
                    cc.vv.AudioManager.playEff("games/GodAthena/", "fly2", true);

                    await this.awaitTime(0.5);
                    cc.find("txt_rewardGold", knife).getComponent(cc.Label).string =
                        Global.formatNumShort(data.item.coin * data.knifeGame.mult);
                    pick1_fazhen_spine.clearTracks();
                    pick1_fazhen_spine.setToSetupPose();
                    pick1_fazhen_spine.setAnimation(0, "animation2", true);
                    await this.awaitTime(0.5);
                }
                // 法阵切换动画
                pick1_fazhen_spine.clearTracks();
                pick1_fazhen_spine.setToSetupPose();
                pick1_fazhen_spine.setAnimation(0, "animation3", true);

                // 文字置灰
                knife.getChildByName("txt_rewardGold").color = cc.Color.GRAY;

                // 播放连线
                cc.vv.AudioManager.playEff("games/GodAthena/", "fly1", true);
                this.playWinLine(knife, curChoice);

                await this.awaitTime(0.2);

                cc.vv.gameData.GetBottomScript().SetWin(data.knifeGame.winCoin);

                await this.awaitTime(0.8);
                this._canSelect = true;
                this.setAutoPlay();
            }
            break;
            case KnifeType.ExtraPick: {
                let pick1_fazhen = knife.getChildByName("pick1_fazhen");
                let pick1_fazhen_spine = pick1_fazhen.getComponent(sp.Skeleton);
                pick1_fazhen.active = true;
                pick1_fazhen_spine.clearTracks();
                pick1_fazhen_spine.setToSetupPose();
                pick1_fazhen_spine.setAnimation(0, "animation", true);

                this._showRewardByType(knife, data.item);

                await this.awaitTime(1);

                let startPos = knife.convertToWorldSpaceAR(cc.v2(0, 0));
                startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                let endPos = this.remainTimes.convertToWorldSpaceAR(cc.v2(0, 0));
                endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                this._generateParticle(startPos, endPos);
                cc.vv.AudioManager.playEff("games/GodAthena/", "fly3", true);

                await this.awaitTime(0.5);
                this._updateRemainTimes();
                this._canSelect = true;
                this.setAutoPlay();
            }
            break;
            case KnifeType.MultAndExtraPick: {
                let pick1_fazhen = knife.getChildByName("pick1_fazhen");
                let pick1_fazhen_spine = pick1_fazhen.getComponent(sp.Skeleton);
                pick1_fazhen.active = true;
                pick1_fazhen_spine.clearTracks();
                pick1_fazhen_spine.setToSetupPose();
                pick1_fazhen_spine.setAnimation(0, "animation", true);

                this._showRewardByType(knife, data.item);

                await this.awaitTime(1);

                if (data.knifeGame.mult !== data.item.cnt) {
                    // 如果与当前倍率不一致，那么就说明需要更新当前倍率的item
                    if (this._curRateItemIndex !== 0) {
                        let preKnife = cc.find("knife_" + this._curRateItemIndex, this.node);
                        cc.find("icon_ratePick", preKnife).color = cc.Color.GRAY;
                        cc.find("icon_ratePick/New Sprite", preKnife).color = cc.Color.GRAY;
                    }
                }
                this._curRateItemIndex = data.choiceId;
                let startPos = knife.convertToWorldSpaceAR(cc.v2(0, 0));
                startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                let endPos = this.remainTimes.convertToWorldSpaceAR(cc.v2(0, 0));
                endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                this._generateParticle(startPos, endPos);
                cc.vv.AudioManager.playEff("games/GodAthena/", "fly3", true);

                await this.awaitTime(0.5);
                this._updateRemainTimes();
                this._canSelect = true;
                this.setAutoPlay();
            }
            break;
            case KnifeType.GodAthena: {
                let renwutouxiang = cc.find("renwutouxiang", knife);
                renwutouxiang.active = true;
                let renwutouxiang_spine = renwutouxiang.getComponent(sp.Skeleton);
                renwutouxiang_spine.clearTracks();
                renwutouxiang_spine.setToSetupPose();
                renwutouxiang_spine.setAnimation(0, "animation", false);
                renwutouxiang_spine.setCompleteListener((track)=>{
                    let name = track.animation ? track.animation.name : "";
                    if (name === "animation") {
                        renwutouxiang_spine.clearTracks();
                        renwutouxiang_spine.setToSetupPose();
                        renwutouxiang_spine.setAnimation(0, "animation2", true);
                    }
                });

                await this.awaitTime(2);

                let wheel_script = cc.find("node_wheel", this.node).getComponent("Athena_Wheel");
                await wheel_script.enterWheel(data);

                cc.find("coin", renwutouxiang).active = true;
                cc.find("coin", renwutouxiang).getComponent(cc.Label).string = Global.formatNumShort(wheel_script.getWinCoin());

                await this.awaitTime(0.5);

                // 文字置灰
                cc.find("coin", renwutouxiang).color = cc.Color.GRAY;

                // 播放连线
                cc.vv.AudioManager.playEff("games/GodAthena/", "fly3", true);
                this.playWinLine(knife, curChoice);

                await this.awaitTime(0.2);

                cc.vv.gameData.GetBottomScript().SetWin(data.knifeGame.winCoin);

                await this.awaitTime(0.8);
                this._canSelect = true;
                this.setAutoPlay();
            }
            break;
        }

        if (data.knifeGame.otherIdxs) {
            // 结束了
            this._canSelect = false;
            for (let i = 0; i < data.knifeGame.otherIdxs.length; i++) {
                let index = data.knifeGame.otherIdxs[i];
                let otherKnife = cc.find("knife_" + index, this.node);
                otherKnife.color = cc.Color.GRAY;
                for (let child of otherKnife.children) {
                    child.color = cc.Color.GRAY;
                }
                this._showRewardByType(otherKnife, data.knifeGame.otherItems[i]);
            }

            await this.awaitTime(1);

            Global.SlotsSoundMgr.stopBgm();
            cc.vv.AudioManager.playEff("games/GodAthena/", "pick1_end", true);

            let node_win = cc.find("node_win", this.node);
            node_win.active = true;
            let bg = cc.find("bg", node_win);
            bg.scale = 0;
            bg.runAction(cc.scaleTo(0.7, 1).easing(cc.easeBackOut()));

            this._winCoin = data.knifeGame.winCoin;

            Global.doRoallNumEff(cc.find("total_win", bg), 0, data.knifeGame.winCoin, 3, null, null, 0, true);

            let btn_collect = cc.find("btn_collect", bg);

            btn_collect.off("click");
            let func = async ()=>{
                btn_collect.off("click");
                cc.vv.gameData.AddCoin(data.knifeGame.winCoin);
                bg.runAction(cc.scaleTo(0.7, 0).easing(cc.easeBackIn()));

                await this.awaitTime(0.7);

                node_win.active = false;
                this._successCallback();
            };

            cc.vv.gameData.checkAutoPlay(btn_collect, func);

            btn_collect.on("click", async ()=>{
                btn_collect.stopAllActions();
                await func();
            });
        }
    },

    /**
     * 播放赢钱线路动画
     * @param fromNode 播放动画节点
     * @param curChoice
     * @returns {Promise<void>}
     */
    async playWinLine(fromNode, curChoice){
        let spNode = cc.find("Canvas/safe_node/footerlianxian");
        let footerjieshou = cc.find("Canvas/safe_node/footerjieshou");
        let winNode = cc.vv.gameData.GetBottomScript().getWinLabelNor();
        let spAnimLength = [765, 605, 448, 240];

        let fromPos = spNode.parent.convertToNodeSpaceAR(fromNode.convertToWorldSpaceAR(cc.v2(0,0)));
        let endPos = spNode.parent.convertToNodeSpaceAR(winNode.convertToWorldSpaceAR(cc.v2(0,0)));

        let v = cc.v2(endPos.x, endPos.y).sub(cc.v2(fromPos.x, fromPos.y));
        let length = v.mag();
        let angle = v.signAngle(cc.v2(-1, 0));
        spNode.active = true;
        spNode.position = fromPos;
        spNode.angle = -angle * cc.macro.DEG +90;
        spNode.scale = length / (spAnimLength[ Math.ceil(curChoice / 4) - 1]);

        spNode.getComponent(sp.Skeleton).setAnimation(0, "animation" + Math.ceil(curChoice / 4), false);
        spNode.getComponent(sp.Skeleton).setCompleteListener(()=>{
            spNode.getComponent(sp.Skeleton).setCompleteListener();
            spNode.active = false;
        })
        footerjieshou.active = true;
        footerjieshou.position = endPos;
        footerjieshou.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        footerjieshou.getComponent(sp.Skeleton).setCompleteListener(()=>{
            footerjieshou.getComponent(sp.Skeleton).setCompleteListener();
            footerjieshou.active = false;
        })
    },

    getWinCoin() {
        return this._winCoin;
    },

    _generateParticle(startPos, endPos) {
        let particle = cc.instantiate(cc.find("beishulizi", this.node.parent));
        particle.parent = this.node.parent;
        particle.position = startPos;
        particle.active = true;
        particle.runAction(cc.sequence(
            cc.moveTo(0.5, endPos),
            cc.removeSelf()
        ));
    },

    /**
     * 显示奖励，仅做显示用，不处理任何逻辑
     * @param node
     * @param item
     * @private
     */
    _showRewardByType(node, item) {
        let atlas = cc.vv.gameData.GetAtlasByName("pick1");
        switch (item.type) {
            case KnifeType.Coin:
                node.getChildByName("txt_rewardGold").active = true;
                node.getChildByName("txt_rewardGold").getComponent(cc.Label).string = Global.formatNumShort(item.coin);
                break;
            case KnifeType.ExtraPick: {
                node.getChildByName("icon_reward").active = true;
                node.getChildByName("icon_reward").getComponent(cc.Sprite).spriteFrame =
                    atlas.getSpriteFrame("theme173_pick1_pick" + item.cnt);
            }
                break;
            case KnifeType.MultAndExtraPick: {
                node.getChildByName("icon_ratePick").active = true;
                node.getChildByName("icon_ratePick").getComponent(cc.Sprite).spriteFrame =
                    atlas.getSpriteFrame("theme173_pick1_multi" + item.cnt);
            }
                break;
            case KnifeType.GodAthena: {
                node.getChildByName("icon_reward").active = true;
                cc.find("icon_reward/head", node).active = true
            }
                break;
        }
    },

    setAutoPlay(){
        let list = [];
        for (let i = 1; i < 16; i++){
            if(this._haveOpenReward.indexOf(i) == -1){
                list.push(i);
            }
        }

        let randomIdx = Global.random(0,list.length-1)
        let self = this;
        cc.vv.gameData.checkAutoPlay(this.node.getChildByName("knife_" + list[randomIdx]),  function (){self.onClickItem(list[randomIdx])});
    },

    onClickItem(i){
        for (let i = 1; i < 16; i++) {
            let knife = this.node.getChildByName("knife_" + i);
            knife.stopAllActions();
        }

        if (!this._canSelect) {
            return;
        }
        if (this._haveOpenReward.indexOf(i) !== -1) {
            return;
        }
        cc.vv.AudioManager.playEff("games/GodAthena/", "pickone", true);
        this._canSelect = false;
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.uid = Global.playerData.uid;
        req.gameid = cc.vv.gameData._gameId;
        req.data = {};
        req.data.rtype = 2;
        req.data.choiceId = i;
        cc.vv.NetManager.send(req);

        this._restCnt--;
        this._updateRemainTimes();
    },

    regiserClickEvent() {
        for (let i = 1; i < 16; i++) {
            let knife = this.node.getChildByName("knife_" + i);
            knife.off(cc.Node.EventType.TOUCH_END);
            knife.on(cc.Node.EventType.TOUCH_END, ()=>{
                this.onClickItem(i);
            });
        }
    },

    reset() {
        for (let i = 1; i < 16; i++) {
            let knife = this.node.getChildByName("knife_" + i);
            knife.color = cc.Color.WHITE;
            for (let child of knife.children) {
                child.color = cc.Color.WHITE;
            }
            knife.getChildByName("bishouxunhuan").active = true;

            let bishouxunhuan = knife.getChildByName("bishouxunhuan").getComponent(sp.Skeleton);
            bishouxunhuan.clearTracks();
            bishouxunhuan.setToSetupPose();
            bishouxunhuan.setAnimation(0, "animation", false);
            bishouxunhuan.setCompleteListener(async (track)=>{
                let name = track.animation ? track.animation.name : "";
                if (name === "animation") {
                    await cc.vv.gameData.awaitTime(Math.random() * 10);

                    bishouxunhuan.clearTracks();
                    bishouxunhuan.setToSetupPose();
                    bishouxunhuan.setAnimation(0, "animation", false);
                }
            });

            knife.getChildByName("bishoudianji").active = false;

            // knife.getChildByName("footerlianxian").active = false;

            knife.getChildByName("pick_zhuanpanlizi").active = false;

            knife.getChildByName("pick1_fazhen").active = false;

            knife.getChildByName("txt_rewardGold").active = false;
            knife.getChildByName("icon_reward").active = false;
            if(cc.find("icon_reward/head", knife)){
                cc.find("icon_reward/head", knife).active = false;
            }
           

            knife.getChildByName("icon_ratePick").active = false;

            knife.getChildByName("renwutouxiang").active = false;
            cc.find("renwutouxiang/coin", knife).active = false;
        }

        let winNode = this.node.getChildByName("node_win");
        winNode.active = false;

        this._canSelect = true;
        this.setAutoPlay();

        this._curRateItemIndex = 0;
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },
});