/**
 * @description
 */

let ShieldType = {
    ExpandingFreeGame: 1,
    PickBonus: 2,
    AthenaProgressive: 3,
    CoinMult: 4,
    AthenaFreeGame: 5
};

cc.Class({
    extends: cc.Component,
    properties: {

        _winCoin: 0,
        _canSelect: true,

        _successCallback: null,
        _resultData: null,
    },

    enterGame() {
        return new Promise((success)=>{
            this.node.active = true;
            this._successCallback = success;
            this._resultData = null;

            cc.vv.AudioManager.playBgm("games/GodAthena/", "free_game_music_advanced", true);

            this.reset();

            this.regiserClickEvent();
        });
    },

    exitGame() {
        this.node.active = false;
        this._successCallback = null;
    },

    async onChooseShield(data) {
        this._resultData = data;
        let shield = cc.find("shield_" + data.choiceId, this.node);
        for (let j = 1; j < 6; j++) {
            let node = this.node.getChildByName("shield_" + j);
            node.stopAllActions();
            node.getChildByName("dunxunhuan").getComponent(sp.Skeleton).setToSetupPose();
            node.getChildByName("dunxunhuan").getComponent(sp.Skeleton).clearTracks();
            node.getChildByName("dunxunhuan").getComponent(sp.Skeleton).setAnimation(0, "animation2", true);
        }

        shield.getChildByName("dunxunhuan").active = false;

        // 翻盾牌
        cc.vv.AudioManager.playEff("games/GodAthena/", "show3", true);
        let fandunpai = cc.find("fandunpai", shield);
        fandunpai.active = true;
        let fandunpai_spine = fandunpai.getComponent(sp.Skeleton);
        fandunpai_spine.clearTracks();
        fandunpai_spine.setToSetupPose();
        fandunpai_spine.setAnimation(0, "animation", false);
        fandunpai_spine.setCompleteListener(() => {
            fandunpai.active = false;
        });

        // 翻虎头
        let fanhutou = cc.find("fanhutou", shield);
        fanhutou.active = true;
        let fanhutou_spine = fanhutou.getComponent(sp.Skeleton);
        fanhutou_spine.clearTracks();
        fanhutou_spine.setToSetupPose();
        fanhutou_spine.setAnimation(0, "animation", false);
        fanhutou_spine.setCompleteListener((track)=>{
            let name = track.animation ? track.animation.name : "";
            if (name === "animation") {
                fanhutou_spine.clearTracks();
                fanhutou_spine.setToSetupPose();
                fanhutou_spine.setAnimation(0, "animation2", true);
            }
        });


        await this.awaitTime(1);

        this._showRewardByType(shield, data.items[data.choiceId - 1]);

        await this.awaitTime(2);
        cc.vv.AudioManager.playEff("games/GodAthena/", "pick2_end", true);
        for (let i = 1; i < 6; i++) {
            if (i !== data.choiceId) {
                let node = this.node.getChildByName("shield_" + i);
                node.getChildByName("dunxunhuan").color = cc.Color.GRAY;
                this._showRewardByType(node, data.items[i - 1]);
            }
        }

        await this.awaitTime(2);

        Global.SlotsSoundMgr.stopBgm();
        switch (data.items[data.choiceId - 1].type) {
            case ShieldType.ExpandingFreeGame:
            case ShieldType.PickBonus:
            case ShieldType.AthenaFreeGame: {
                this._successCallback();
            }
            break;
            case ShieldType.CoinMult: {
                cc.vv.AudioManager.playEff("games/GodAthena/", "free2_dialog_collect_show", true);
                let node_win = cc.find("node_win", this.node);
                node_win.active = true;
                let bg = cc.find("bg", node_win);
                bg.scale = 0;
                bg.runAction(cc.scaleTo(0.7, 1).easing(cc.easeBackOut()));

                Global.doRoallNumEff(cc.find("total_win", bg), 0, data.winCoin, 3, null, null, 0, true);

                cc.vv.gameData.AddCoin(data.winCoin);

                let btn_collect = cc.find("btn_collect", bg);
                btn_collect.off("click");
                let func = async ()=>{
                    btn_collect.off("click");
                    bg.runAction(cc.scaleTo(0.7, 0).easing(cc.easeBackIn()));

                    await this.awaitTime(0.7);

                    node_win.active = false;
                    this._successCallback();
                    this.exitGame();
                };

                cc.vv.gameData.checkAutoPlay(btn_collect, func);

                btn_collect.on("click", async ()=>{
                    btn_collect.stopAllActions();
                    await func();
                });
            }
            break;
            case ShieldType.AthenaProgressive: {
                this._successCallback();
            }
            break;
        }
    },

    getResultData() {
        return this._resultData;
    },

    _showRewardByType(node, shieldResult) {
        // let atlas = cc.vv.gameData.GetAtlasByName("pick2");
        let tujiatlas = cc.vv.gameData.GetAtlasByName("tuji");

        switch (shieldResult.type) {
            case ShieldType.ExpandingFreeGame:
                node.getChildByName("result").active = true;
                node.getChildByName("num").active = false;

                node.getChildByName("result").getComponent(cc.Sprite).spriteFrame =
                    tujiatlas.getSpriteFrame("theme173_pick2_r3");
                break;
            case ShieldType.PickBonus: {
                node.getChildByName("result").active = true;
                node.getChildByName("num").active = false;

                node.getChildByName("result").getComponent(cc.Sprite).spriteFrame =
                    tujiatlas.getSpriteFrame("theme173_pick2_r5");
            }
                break;
            case ShieldType.AthenaProgressive: {
                node.getChildByName("result").active = true;
                node.getChildByName("num").active = false;

                node.getChildByName("result").getComponent(cc.Sprite).spriteFrame =
                tujiatlas.getSpriteFrame("theme173_pick2_r2n");
            }
                break;
            case ShieldType.CoinMult: {
                node.getChildByName("result").active = false;
                node.getChildByName("num").active = true;
                node.getChildByName("num").getComponent(cc.Label).string =
                    Global.formatNumShort(shieldResult.mult * cc.vv.gameData.GetTotalBet(),0);
            }
                break;
            case ShieldType.AthenaFreeGame: {
                node.getChildByName("result").active = true;
                node.getChildByName("num").active = false;

                node.getChildByName("result").getComponent(cc.Sprite).spriteFrame =
                tujiatlas.getSpriteFrame("theme173_pick2_r4n");
            }
            break;
        }


        let action = cc.scaleTo(0.5, 1);
        switch (shieldResult.type) {
            case ShieldType.ExpandingFreeGame:
            case ShieldType.PickBonus:
            case ShieldType.AthenaProgressive:
            case ShieldType.AthenaFreeGame:{
                node.getChildByName("result").scale = 0;
                node.getChildByName("result").runAction(action);
            }
                break;
            case ShieldType.CoinMult: {
                node.getChildByName("num").scale = 0;
                node.getChildByName("num").runAction(action);
            }
                break;
        }
    },

    setAutoPlay(){
        let list = [];
        for (let i = 1; i < 6; i++){
            // if(this._haveOpenReward.indexOf(i) == -1){
                list.push(i);
            // }
        }

        let randomIdx = Global.random(0,list.length-1)
        let self = this;
        cc.vv.gameData.checkAutoPlay(this.node.getChildByName("shield_" + list[randomIdx]),  function (){self.onClickItem(list[randomIdx])});
    },

    onClickItem(i){
        for (let i = 1; i < 6; i++) {
            let shield = this.node.getChildByName("shield_" + i);
            shield.stopAllActions();
        }

        if (!this._canSelect) {
            return;
        }
        cc.vv.AudioManager.playEff("games/GodAthena/", "choose", true);
        this._canSelect = false;
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.uid = Global.playerData.uid;
        req.gameid = cc.vv.gameData._gameId;
        req.data = {};
        req.data.rtype = 3;
        req.data.choiceId = i;
        cc.vv.NetManager.send(req);
    },

    regiserClickEvent() {
        for (let i = 1; i < 6; i++) {
            let shield = this.node.getChildByName("shield_" + i);
            shield.off(cc.Node.EventType.TOUCH_END);
            shield.on(cc.Node.EventType.TOUCH_END, () => {
                this.onClickItem(i);
            });
        }
    },

    reset() {
        for (let i = 1; i < 6; i++) {
            let shield = this.node.getChildByName("shield_" + i);
            shield.getChildByName("fandunpai").active = false;
            shield.getChildByName("fanhutou").active = false;
            shield.getChildByName("result").active = false;
            shield.getChildByName("num").active = false;

            let dunxunhuan = shield.getChildByName("dunxunhuan");
            let dunxunhuan_spine = dunxunhuan.getComponent(sp.Skeleton);
            dunxunhuan.active = true;
            dunxunhuan.color = cc.Color.WHITE;
            dunxunhuan_spine.clearTracks();
            dunxunhuan_spine.setToSetupPose();
            dunxunhuan_spine.setAnimation(0, "animation", false);
            dunxunhuan_spine.setCompleteListener(async (track) => {
                let name = track.animation ? track.animation.name : "";
                if (name === "animation") {
                    await cc.vv.gameData.awaitTime(Math.random() * 10);

                    dunxunhuan_spine.clearTracks();
                    dunxunhuan_spine.setToSetupPose();
                    dunxunhuan_spine.setAnimation(0, "animation", false);
                }
            })
        }

        this._canSelect = true;
        this.setAutoPlay();
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },
});