/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        items: [cc.Node],
        rate_2: cc.Node,
        rate_3: cc.Node,
        zhuanpanlizi: cc.Node,
        zhuanpanzhongjiang: cc.Node,

        _successCallback: null,
        _resultItem: null,
        _startMove: false,
        _speed: 5,
        _maxSpeed: 10,
        _minSpeed: 0.5,
        _speedOffset: 0.02,
        _count: 12,
        _needStop: false,
        _bottomPosY: 0,
        _backMove: false,
        _resultData: null,
        _wheelConfig: null,
        _winCoin: 0,
    },

    onLoad() {
        this._bottomPosY = this.items[0].y - this.items[0].height;
    },

    async enterWheel(data) {
        return new Promise(async (success)=>{
            this._successCallback = success;
            this._resultData = data;
            this._wheelConfig = data.item.items;

            this.node.active = true;

            for (let i = 0; i < 10; i++) {
                let config = this._wheelConfig[i];
                let node = this.items[i];
                cc.find("coin", node).getComponent(cc.Label).string =
                    Global.formatNumShort(config.mult * cc.vv.gameData.GetTotalBet());
            }

            let parent_node = cc.find("parent", this.node);
            parent_node.runAction(cc.scaleTo(0.5, 1).easing(cc.easeBackOut()));

            this.rate_2.active = data.knifeGame.mult === 2;
            this.rate_3.active = data.knifeGame.mult === 3;

            this._resultItem = this.items[data.item.resultId - 1];

            this._winCoin = this._wheelConfig[this._resultData.item.resultId - 1].mult *
                this._resultData.knifeGame.mult * cc.vv.gameData.GetTotalBet();

            await this.awaitTime(2);

            this._startMove = true;
            cc.vv.AudioManager.playEff("games/GodAthena/", "wheel_spin", true);
            this.zhuanpanlizi.active = true;
        })
    },

    getWinCoin() {
        return this._winCoin;
    },

    async _moveEnd() {
        this.zhuanpanzhongjiang.active = true;

        cc.vv.AudioManager.playEff("games/GodAthena/", "wheel_win", true);

        await this.awaitTime(1);

        if (this._resultData.knifeGame.mult !== 1) {
            let startPos = this.rate_2.convertToWorldSpaceAR(cc.v2(0, 0));
            startPos = this.node.convertToNodeSpaceAR(startPos);
            let endPos = this._resultItem.convertToWorldSpaceAR(cc.v2(0, 0));
            endPos = this.node.convertToNodeSpaceAR(endPos);

            let particle = cc.instantiate(cc.find("beishulizi", this.node.parent.parent));
            particle.parent = this.node;
            particle.position = startPos;
            particle.active = true;
            particle.runAction(cc.sequence(
                cc.moveTo(0.5, endPos),
                cc.removeSelf()
            ));

            await this.awaitTime(0.5);

            cc.find("coin", this._resultItem).getComponent(cc.Label).string =
                Global.formatNumShort(this._winCoin);

            await this.awaitTime(1);
        }

        let parent_node = cc.find("parent", this.node);
        parent_node.runAction(cc.scaleTo(0.5, 0).easing(cc.easeBackIn()));

        await this.awaitTime(0.5);

        this._successCallback();

        this._speed = 5;
        this._successCallback = null;
        this._resultItem = null;
        this._count = 12;
        this._needStop = false;
        this._resultData = null;
        this.zhuanpanzhongjiang.active = false;

        this.node.active = false;
    },

    update(dt) {
        if (this._startMove) {
            if (!this._needStop) {
                this._speed += this._speedOffset;
                if (this._speed >= this._maxSpeed) {
                    this._speed = this._maxSpeed;
                }
            } else {
                this._speed -= this._speedOffset;
                if (this._speed <= this._minSpeed) {
                    this._speed = this._minSpeed;
                }
            }

            if (this._count === 0 && this._resultItem.y <= 5 * this._resultItem.height) {
                this._needStop = true;
                this.zhuanpanlizi.active = false;
            }

            if (this._needStop && this._resultItem.y < 0) {
                this._startMove = false;
                this._backMove = true;
            }

            for (let item of this.items) {
                if (item.y <= this._bottomPosY) {
                    item.y += this.items.length * item.height;
                    if (item === this._resultItem) {
                        this._count--;
                        if (this._count <= 0) {
                            this._count = 0;
                        }
                    }
                }

                item.y -= this._speed;
            }
        }

        if (this._backMove) {
            for (let item of this.items) {
                item.y += this._minSpeed;
            }

            if (this._resultItem.y > -1 && this._resultItem.y < 1) {
                this._backMove = false;
                this._moveEnd();
            }
        }
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },
});