            cc.find("reels_frame/common_node", this.node).active = true;
            if (this._gameInfo.bonusTrail.count === 16) {
                this._curBonusCount = 0;
                for (let i = 1; i < 17; i++) {
                    cc.find("reels_frame/common_node/bonus_node/icon_" + i, this.node).active = false;
                }
            }
            cc.find("reels_frame/expand_free_node", this.node).active = false;
            // cc.find("LMSlots_PrizePool_1/prizePool_Progressive", this.node.parent).active = true;
